/**
 * Load extracted constituency JSON from public/constituency-data.
 * Generated by: npm run extract-constituencies
 *
 * Server-only (uses Node fs). Client code must import types from
 * `@/lib/constituency-types` instead of this module.
 */

import fs from "fs";
import path from "path";
import type {
  ConstituencyKind,
  ConstituencyLink,
  ConstituencySeat,
  ConstituencySeatTotals,
  ConstituencyWardLink,
  ManualLinksFile,
  UnmappedSeat,
} from "@/lib/constituency-types";

export type {
  ConstituencyKind,
  ConstituencyLink,
  ConstituencySeat,
  ConstituencySeatTotals,
  ConstituencyWardLink,
  ManualLinksFile,
  UnmappedSeat,
} from "@/lib/constituency-types";

const NATIONAL_CODE = "NATIONAL";

let cache: {
  senatorial: ConstituencySeat[];
  federal: ConstituencySeat[];
  stateAssembly: ConstituencySeat[];
  links: Record<string, ConstituencyLink>;
  unmapped: UnmappedSeat[];
} | null = null;

function dataDir(): string {
  const candidates = [
    path.join(process.cwd(), "public", "constituency-data"),
    path.join(process.cwd(), ".next", "server", "public", "constituency-data"),
    path.join(process.cwd(), ".next", "standalone", "public", "constituency-data"),
  ];
  for (const p of candidates) {
    try {
      if (fs.existsSync(p)) return p;
    } catch {
      /* ignore */
    }
  }
  return candidates[0];
}

function readJson<T>(file: string, fallback: T): T {
  const p = path.join(dataDir(), file);
  try {
    if (!fs.existsSync(p)) return fallback;
    return JSON.parse(fs.readFileSync(p, "utf8")) as T;
  } catch (err) {
    console.error(`[constituency-data] failed to read ${file}:`, err);
    return fallback;
  }
}

function load() {
  if (cache) return cache;
  cache = {
    senatorial: readJson("senatorial.json", []),
    federal: readJson("federal.json", []),
    stateAssembly: readJson("state_assembly.json", []),
    links: readJson("constituency_links.json", {}),
    unmapped: readJson("unmapped.json", []),
  };
  return cache;
}

/** Bust cache after admin writes manual_links (dev / same process). */
export function reloadConstituencyData() {
  cache = null;
}

export function listSenatorialDistricts(stateId?: string): ConstituencySeat[] {
  const all = load().senatorial;
  if (!stateId) return all;
  const s = stateId.toLowerCase();
  return all.filter((x) => x.stateId.toLowerCase() === s);
}

export function listFederalConstituencies(stateId?: string): ConstituencySeat[] {
  const all = load().federal;
  if (!stateId) return all;
  const s = stateId.toLowerCase();
  return all.filter((x) => x.stateId.toLowerCase() === s);
}

export function listStateAssemblyConstituencies(stateId?: string): ConstituencySeat[] {
  const all = load().stateAssembly;
  if (!stateId) return all;
  const s = stateId.toLowerCase();
  return all.filter((x) => x.stateId.toLowerCase() === s);
}

export function getConstituencyByCode(code: string): ConstituencySeat | null {
  const c = code.trim();
  if (!c) return null;
  const data = load();
  return (
    data.senatorial.find((x) => x.code === c) ||
    data.federal.find((x) => x.code === c) ||
    data.stateAssembly.find((x) => x.code === c) ||
    null
  );
}

export function getConstituencyLink(code: string): ConstituencyLink | null {
  return load().links[code.trim()] ?? null;
}

export function listUnmappedConstituencies(): UnmappedSeat[] {
  return load().unmapped;
}

export function listConstituencyLinks(): Record<string, ConstituencyLink> {
  return load().links;
}

export function nationalAgentPost(): { code: string; name: string } {
  return { code: NATIONAL_CODE, name: "National Collation Agent" };
}

export function isNationalCode(code: string | null | undefined): boolean {
  return (code ?? "").trim().toUpperCase() === NATIONAL_CODE;
}

/** Kind expected for a given agent level. */
export function constituencyKindForAgentLevel(
  level: string
): ConstituencyKind | "national" | null {
  if (level === "senatorial") return "senatorial";
  if (level === "house_of_reps") return "federal";
  if (level === "state_assembly") return "state_assembly";
  if (level === "national") return "national";
  return null;
}

export function readManualLinks(): ManualLinksFile {
  return readJson("manual_links.json", { links: {} });
}

export function writeManualLinks(file: ManualLinksFile): void {
  const dir = dataDir();
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, "manual_links.json"), JSON.stringify(file, null, 2));
  reloadConstituencyData();
}

/**
 * Patch constituency_links.json + unmapped.json after an admin saves ward codes.
 * Ward rows are minimal (locationCode only) until the next full extract rebuilds metadata.
 */
export function applyManualLinkToRuntimeFiles(code: string, wardLocationCodes: string[]): void {
  const dir = dataDir();
  const linksPath = path.join(dir, "constituency_links.json");
  const unmappedPath = path.join(dir, "unmapped.json");
  const links = readJson<Record<string, ConstituencyLink>>("constituency_links.json", {});
  const seat =
    getConstituencyByCode(code) ||
    ({
      code,
      name: code,
      stateId: "",
      stateName: "",
      composition: "",
      collationCentre: "",
    } satisfies ConstituencySeat);

  const kind: ConstituencyKind =
    code.startsWith("SD/") ? "senatorial" : code.startsWith("FC/") ? "federal" : "state_assembly";

  const wards: ConstituencyWardLink[] = wardLocationCodes.map((locationCode) => {
    const parts = locationCode.split("/");
    return {
      stateId: seat.stateId,
      stateName: seat.stateName,
      stateCode: parts[0] || "",
      lgaId: "",
      lgaName: "",
      lgaCode: parts[1] || "",
      wardId: "",
      wardName: "",
      wardCode: parts[2] || "",
      locationCode,
      puCount: 0,
    };
  });

  links[code] = {
    code,
    kind,
    status: wards.length ? "mapped" : "unmapped",
    wards,
    source: "manual",
  };
  fs.writeFileSync(linksPath, JSON.stringify(links, null, 2));

  const unmapped = readJson<UnmappedSeat[]>("unmapped.json", []).filter((u) => u.code !== code);
  if (!wards.length) {
    unmapped.push({
      code,
      name: seat.name,
      kind,
      stateId: seat.stateId,
      stateName: seat.stateName,
      composition: seat.composition,
      reason: "manual_cleared",
    });
  }
  fs.writeFileSync(unmappedPath, JSON.stringify(unmapped, null, 2));
  reloadConstituencyData();
}
